    /// <summary>
    /// MPJ_21178_VendorGlobal By chaminda on 04 Mar 2022
    /// Find the record
    /// </summary>
    /// <param name="_metVendParentCompanyID"> Get vendor parent company id</param>
    /// <param name="_forupdate"> Get update parameter </param>
    /// <param name="_concurrencyModel"> Get concurrency model parameter </param>
    /// /// <returns>
    /// Return table record
    /// </returns>
    static METVendParentCompany find(METVendParentCompanyID _metVendParentCompanyID, boolean _forupdate = false, ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
    {
        METVendParentCompany metVendParentCompany;

        metVendParentCompany.selectForUpdate(_forupdate);
        metVendParentCompany.concurrencyModel(_concurrencyModel);

        select firstonly metVendParentCompany
            where metVendParentCompany.VendParentCompanyID == _metVendParentCompanyID;
         
        return metVendParentCompany;
    }

    /// <summary>
    /// To Find the record
    /// </summary>
    /// <param name="_RefRecId"> Get record ID</param>
    /// <param name="_forupdate"> Get update parameter </param>
    /// <param name="_concurrencyModel"> Get concurrency model parameter </param>
    /// <returns>
    /// Return table record
    /// </returns>
    static METVendParentCompany findbyRecId(RefRecId _RefRecId, boolean _forupdate = false, ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
    {
        METVendParentCompany metVendParentCompany;

        metVendParentCompany.selectForUpdate(_forupdate);
        metVendParentCompany.concurrencyModel(_concurrencyModel);

        select firstonly metVendParentCompany
            where metVendParentCompany.recId == _RefRecId;
         
        return metVendParentCompany;
    }

    /// <summary>
    /// Find table record by VendLEId
    /// </summary>
    /// <param name = "_vendLegalEntityID">VendLEId</param>
    /// <returns>table buffer</returns>
    static METVendParentCompany findbyVendLegalEntityId(METVendLegalEntityID _vendLegalEntityID)
    {
        METVendParentCompany    METVendParentCompany;
        METVendLegalEntity      METVendLegalEntity;

        select firstonly metVendParentCompany
            exists join METVendLegalEntity 
            where METVendLegalEntity.VendLegalEntityID == _vendLegalEntityID 
            && METVendLegalEntity.VendParentCompany == metVendParentCompany.recId ;
                 
        return metVendParentCompany;
    }
